  assert.match(text, /Blue Fern Bakery\n/);
  assert.match(text, /Total: /);
});

test('renderInvoiceText produces the same output for identical invoices', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const text1 = renderInvoiceText(invoice);
  const text2 = renderInvoiceText(invoice);

  assert.equal(text1, text2);
});

test('renderInvoiceText shows discount on line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(lines[2], /10% off/);
  assert.match(lines[2], /-€95.00/);
});

test('renderInvoiceText shows subtotal and discount line when discounts apply', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 5 },
    ],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.match(text, /Subtotal:/);
  assert.match(text, /Discount:/);
  assert.match(lines[lines.length - 1], /^Total:/);
});

test('renderInvoiceText does not show discount line when no discounts', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('Subtotal:'));
  assert.ok(!text.includes('Discount:'));
});

test('renderInvoiceText handles decimal discount percentages', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 12.5 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /12.5% off/);
});

test('renderInvoiceText with 100% discount shows zero total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[lines.length - 1], 'Total: €0.00');
});

test('renderInvoiceText shows VAT line for products with VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /VAT:/);
  assert.match(text, /€/);
});

test('renderInvoiceText does not show VAT line when no VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('VAT:'));
});

test('renderInvoiceText shows VAT just before total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const invoice = result.value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  const secondLastLine = lines[lines.length - 2];

  assert.match(lastLine, /^Total:/);
  assert.match(secondLastLine, /^VAT:/);
});

test('renderInvoiceText with discount and VAT shows subtotal, discount, VAT, and total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
