import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a valid invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DEV-HOUR');
  assert.equal(line1.name, 'Development (hour)');
  assert.equal(line1.qty, 5);
  assert.equal(line1.unitPrice, 9500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'LOGO-PACK');
  assert.equal(line2.name, 'Logo package');
  assert.equal(line2.qty, 1);
  assert.equal(line2.unitPrice, 120000);
  assert.equal(line2.vatRate, 21);
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice returns DATE_INVALID for bad date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026/10/07',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns DATE_INVALID for non-existent date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice returns QTY_INVALID for non-integer quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns QTY_INVALID for zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns QTY_INVALID for negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice returns UNKNOWN_SKU for unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice stops at first error in lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: -5 },
      { sku: 'UNKNOWN-SKU', qty: 1 },
    ],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const linesCopy = JSON.parse(JSON.stringify(lines));
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, linesCopy);
});

test('createInvoice includes VAT-exempt products', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 0);
});

test('createInvoice handles mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].vatRate, 21);
  assert.equal(result.value.lines[1].vatRate, 9);
  assert.equal(result.value.lines[2].vatRate, 0);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 9500 }), 47500);
  assert.equal(lineTotal({ qty: 100, unitPrice: 37 }), 3700);
});

test('lineTotal works with zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('lineTotal works with large numbers', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 120000 }), 120000000);
});

test('invoiceTotals returns subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 0 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 167500, discount: 0, vat: 0, total: 167500 });
});

test('invoiceTotals sums multiple lines correctly', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 9500, discountPercent: 0, vatRate: 0 },
      { qty: 1, unitPrice: 37, discountPercent: 0, vatRate: 0 },
      { qty: 1, unitPrice: 1500, discountPercent: 0, vatRate: 0 },
      { qty: 1, unitPrice: 6000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17037);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 17037);
});

test('invoiceTotals works with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, { subtotal: 0, discount: 0, vat: 0, total: 0 });
});

test('invoiceTotals returns fresh object', () => {
  const invoice = { lines: [{ qty: 1, unitPrice: 1000 }] };
  const totals1 = invoiceTotals(invoice);
  const totals2 = invoiceTotals(invoice);
  assert.deepEqual(totals1, totals2);
  assert.notStrictEqual(totals1, totals2);
});

test('invoiceTotals works with created invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expected = 8 * 9500 + 1 * 120000;
  const expectedVat = Math.round((8 * 9500 * 21) / 100) + Math.round((1 * 120000 * 21) / 100);
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expected + expectedVat);
});

test('addLine adds a new line to an invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 2);
  assert.equal(addResult.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(addResult.value.lines[1].qty, 1);
  assert.equal(addResult.value.lines[1].unitPrice, 120000);
});

test('addLine increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const invoice = result.value;

  const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines.length, 1);
  assert.equal(addResult.value.lines[0].qty, 8);
  assert.equal(addResult.value.lines[0].sku, 'DEV-HOUR');
});

test('addLine returns QTY_INVALID for non-positive quantities', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = result.value;

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 0 }), {
    ok: false,
    error: 'QTY_INVALID',
